user_behaviour_ui <- function(id) { ns<-NS(id); lab_section(c("Read an interaction sequence.","Separate observations from explanations.","Recognise that simulated traces are not human evidence."),tagList(div(class="alert alert-warning",tags$strong("SIMULATED DATA · "),"Illustrative trace generated for this exercise; no participants were observed."), selectInput(ns("scenario"),"Scenario",c("Course search","Event registration")), actionButton(ns("run"),"Show simulated trace",class="btn-primary"), uiOutput(ns("trace"))),"What alternative explanation could account for the pause? What evidence would you collect ethically?") }
user_behaviour_server <- function(id) { moduleServer(id,function(input,output,session){ shown<-reactiveVal(FALSE); observeEvent(input$run,shown(TRUE)); output$trace<-renderUI({req(shown()); steps<-if(input$scenario=="Course search") c("Home · 3 s","Search · 8 s","Results · 14 s","Course detail · 22 s") else c("Event page · 4 s","Registration form · 11 s","Help link · 17 s","Confirmation · 31 s"); tagList(tags$ol(lapply(steps,tags$li)),p(class="footnote","Synthetic example only. Durations are illustrative, not measured."))}) }) }
